    "/api/services/sessions": {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        /**
         * Get list of sessions with flexible filtering (unified endpoint)
         * @description Retrieve sessions with support for multiple query combinations:
         *
         *           Query Parameters:
         *           - sessionType (optional): Filter by session type, supports single or multiple values
         *             * Not provided: returns all session types
         *             * Single: ?sessionType=regular_mentoring
         *             * Multiple: ?sessionType=regular_mentoring&sessionType=gap_analysis
         *           - studentId (optional): Filter by specific student ID
         *           - mentorId (optional): Filter by specific mentor ID
         *           - counselorId (optional): Filter by specific counselor ID (counselor role only)
         *           - status (optional): Filter by session status (SCHEDULED, COMPLETED, CANCELLED, etc.)
         *           - startDate (optional): Filter by start date
         *           - endDate (optional): Filter by end date
         *           - page (optional): Pagination page number
         *           - limit (optional): Results per page
         *
         *           Examples:
         *           - GET /api/services/sessions (returns all types)
         *           - GET /api/services/sessions?sessionType=regular_mentoring
         *           - GET /api/services/sessions?sessionType=gap_analysis&studentId=xxx
         *           - GET /api/services/sessions?sessionType=regular_mentoring&sessionType=gap_analysis
         *           - GET /api/services/sessions?sessionType=ai_career&mentorId=xxx&studentId=yyy
         */
        get: operations["SessionController_getSessionsList"];
        put?: never;
        /**
         * Create a new session (unified endpoint)
         * @description Creates a new session asynchronously. Session types are defined in session_types.
         *
         *           Sync Flow (returns immediately):
         *           1. Create calendar slots for mentor and student
         *           2. Create session record with PENDING_MEETING status
         *           3. Return response with sessionId and status
         *
         *           Async Flow (runs in background):
         *           1. Create meeting link via third-party API
         *           2. Update session with meeting_id and status=SCHEDULED
         *           3. Publish SESSION_BOOKED_EVENT
         *
         *           Client should poll GET /api/services/sessions/:id to check status and get meetingUrl
         */
        post: operations["SessionController_createSession"];
        delete?: never;
        options?: never;
        head?: never;
        patch?: never;
        trace?: never;
    };
    "/api/services/sessions/completed": {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        get?: never;
        put?: never;
        /**
         * Backfill an already-completed session
         * @description Records a session that was already taught (offline or a pre-existing online
         *           meeting) but never entered the system.
         *
         *           Flow (synchronous):
         *           1. Create service hold, calendar slots, and a manually-registered meeting
         *              record (provider "manual", status "ended") — no third-party meeting is created
         *           2. Link the meeting to the session and calendar slots
         *           3. Drive the standard completion pipeline: entitlement deduction and mentor
         *              billing/evaluation happen exactly like a normal completed session
         *
         *           Returns the session with status "completed". Failed completion attempts remove
         *           the backfill artifacts so the same idempotency key can be retried safely.
         */
        post: operations["SessionController_createCompletedSession"];
        delete?: never;
        options?: never;
        head?: never;
        patch?: never;
        trace?: never;
    };
